CREATE TABLE "outlook_navigation" ("device_id" text PRIMARY KEY REFERENCES "outlook_device"("device_id") ON DELETE CASCADE, "challenge_hash" text NOT NULL, "expires_at" timestamp NOT NULL, "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "outlook_bridge_ticket" ("ticket_hash" text PRIMARY KEY, "device_id" text NOT NULL REFERENCES "outlook_device"("device_id") ON DELETE CASCADE, "challenge_hash" text NOT NULL, "session_id" text NOT NULL, "user_id" text NOT NULL REFERENCES "user"("id") ON DELETE CASCADE, "transport_id" text NOT NULL REFERENCES "mailbox_transport"("id") ON DELETE CASCADE, "store_id" text NOT NULL, "action" text NOT NULL, "operation_id" text, "declared_scope" text, "expires_at" timestamp NOT NULL, "consumed_at" timestamp);
CREATE INDEX "outlook_bridge_ticket_expiry_idx" ON "outlook_bridge_ticket" ("expires_at");
CREATE INDEX "outlook_bridge_ticket_navigation_idx" ON "outlook_bridge_ticket" ("device_id", "challenge_hash");
CREATE TABLE "outlook_approved_folder" ("transport_id" text NOT NULL REFERENCES "mailbox_transport"("id") ON DELETE CASCADE, "store_id" text NOT NULL, "folder_id" text NOT NULL, "kind" text NOT NULL, "approved_at" timestamp NOT NULL DEFAULT now(), PRIMARY KEY("transport_id", "store_id", "folder_id"));
CREATE TABLE "outlook_move_receipt" ("transport_id" text NOT NULL REFERENCES "mailbox_transport"("id") ON DELETE CASCADE, "device_id" text NOT NULL REFERENCES "outlook_device"("device_id") ON DELETE CASCADE, "operation_id" text NOT NULL, "scope_hash" text NOT NULL, "count" integer NOT NULL, "approved_at" timestamp NOT NULL DEFAULT now(), PRIMARY KEY("transport_id", "device_id", "operation_id"));
CREATE INDEX "outlook_move_receipt_budget_idx" ON "outlook_move_receipt" ("transport_id", "approved_at");
